//! 🧪️ Actual inline scalar receipt bytes preserve failed effects and maximum-width original identities.
use super::*;
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_actor_fixed_native_receipt_preserves_raw_spend_and_all_u64_axes_without_heap(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let expected=fixture["failureHex"].as_str().unwrap();let expected:Vec<u8>=(0..expected.len()).step_by(2).map(|index|u8::from_str_radix(&expected[index..index+2],16).unwrap()).collect();
 let original=OriginalActorFixedCall{input:RetainedTurnInput{operation:71,generation:3,epoch:24,grant:RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:7,maximum_capacity_bytes:512,maximum_release_bytes:512,maximum_depth:8}},spent:RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()},kind:OriginalActorFixedKind::Failure{authority:None}};
 let(mut wire,heap)=observe(OriginalActorFixedReceipt::empty);assert_eq!(heap,(0,0));let backing=wire.bytes().as_ptr();let(_,heap)=observe(||wire.write(original));assert_eq!(heap,(0,0));assert_eq!(wire.bytes().as_slice(),expected);let(decoded,heap)=observe(||OriginalActorFixedReceipt::read(wire.bytes()));assert_eq!(heap,(0,0));assert_eq!(decoded.unwrap(),original);assert_eq!(wire.bytes().as_ptr(),backing);
 for kind in [None,Some(ValueRefusalKind::InvalidValue),Some(ValueRefusalKind::Canceled),Some(ValueRefusalKind::OwnershipLimit),Some(ValueRefusalKind::AllocationFailed),Some(ValueRefusalKind::WorkLimit),Some(ValueRefusalKind::DepthLimit),Some(ValueRefusalKind::UnsupportedOwner),Some(ValueRefusalKind::InvariantViolated)]{for variant in [OriginalActorFixedKind::Failure{authority:kind},OriginalActorFixedKind::Admission{ready:false,refusal:kind},OriginalActorFixedKind::Close{complete:false,blocked:false,refusal:kind}]{let actual=OriginalActorFixedCall{kind:variant,..original};let(decoded,heap)=observe(||{wire.write(actual);OriginalActorFixedReceipt::read(wire.bytes())});assert_eq!(heap,(0,0));assert_eq!(decoded.unwrap(),actual);}}
 let mut excessive=original;excessive.spent.copied_items=9;excessive.spent.copied_bytes=8192;let(decoded,heap)=observe(||{wire.write(excessive);OriginalActorFixedReceipt::read(wire.bytes())});assert_eq!(heap,(0,0));assert_eq!(decoded.unwrap(),excessive);assert!(excessive.input.return_original(excessive.spent).is_err());
 let maximum=OriginalActorFixedCall{input:RetainedTurnInput{operation:u64::MAX,generation:u64::MAX,epoch:u64::MAX,grant:RetainedCloneGrant{maximum_items:usize::MAX,maximum_copy_bytes:usize::MAX,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX}},spent:RetainedCloneProgress{copied_items:usize::MAX,copied_bytes:usize::MAX,retained_capacity_bytes:usize::MAX,released_bytes:usize::MAX},..original};let(decoded,heap)=observe(||{wire.write(maximum);OriginalActorFixedReceipt::read(wire.bytes())});assert_eq!(heap,(0,0));assert_eq!(decoded.unwrap(),maximum);assert_eq!(&wire.bytes()[8..32],&[255;24]);
 for(index,value)in[(0,0),(4,4),(5,3),(6,9),(7,1)]{let mut invalid=*wire.bytes();invalid[index]=value;let(result,heap)=observe(||OriginalActorFixedReceipt::read(&invalid));assert_eq!(heap,(0,0));assert!(result.is_err());}let(result,heap)=observe(||OriginalActorFixedReceipt::read(&wire.bytes()[..103]));assert_eq!(heap,(0,0));assert!(result.is_err());assert_eq!(observe(||drop(wire)).1,(0,0));
 eprintln!("[DEBUG] Actual original fixed actor receipt104 bytes same inline backing={backing:p},raw failure1/copy7 and excess9/copy8192 preserved,all27 cause/phase variants and all12 maximum scalars nativewrite/read/refusal/terminalDrop heap0; ABI caller transport remains separate");
}
